package ama.storage;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import ama.transcript.*;import static org.junit.jupiter.api.Assertions.*;
class Task10SafetyRollbackCasIT extends Task10AdoptIT {
 @Override javax.sql.DataSource createSource(){return new Task10AtomicTraceSource(ama.minutes.Task10Source.open());}
 TranscriptAcquisitionBudget limits(){return new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,8388608,128,256,256);}
 @Override void afterCandidate(Map<String,Object> candidate,JdbcMinutesFactsReader.Snapshot facts)throws Exception {
  var trace=(Task10AtomicTraceSource)source;var authority=ama.api.Task09RuntimeProbe.components(app).authority();var saved=new JdbcMinutesSavedCommands(authority,this::snapshot,pin,limits());String id=(String)candidate.get("id"),input=(String)candidate.get("input_id"),fingerprint=(String)candidate.get("input_fingerprint");var stages=new ArrayList<String>();
  var prefixes=new ArrayList<String>();for(String table:List.of("minutes_revision","element_set","source_locator","minutes_element","action_item","action_suggestion","evidence_link","sensitive_detection","sensitive_detection_source","background_note","background_note_source"))prefixes.add("INSERT INTO "+table+"(");prefixes.addAll(List.of("READBACK","UPDATE generation_candidate SET state='ADOPTED'","UPDATE meeting SET minutes_revision_id","UPDATE idempotency_record SET result_id","INSERT INTO audit_event","INSERT INTO task_outbox","COMMIT"));
  for(String prefix:prefixes){var baseline=state();var started=new AtomicBoolean();var hit=new AtomicBoolean();trace.events.clear();trace.before=sql->{if(sql.startsWith("INSERT INTO minutes_revision("))started.set(true);boolean readback=prefix.equals("READBACK")&&sql.startsWith("SELECT ")&&Arrays.stream(Thread.currentThread().getStackTrace()).anyMatch(f->f.getClassName().equals("ama.transcript.MinutesSavedWriter")&&f.getMethodName().equals("writeAndReadback"));if(started.get()&&(readback||sql.startsWith(prefix))&&hit.compareAndSet(false,true))throw new IllegalStateException("TASK10_ROLLBACK_PROBE");};trace.beforeCommit=()->{if(prefix.equals("COMMIT")&&started.get()&&hit.compareAndSet(false,true))throw new IllegalStateException("TASK10_PRECOMMIT_PROBE");};try{assertThrows(RuntimeException.class,()->saved.adopt(actor(),meeting,"rollback-adopt",4,id,input,fingerprint,UUID.randomUUID().toString()),prefix);}finally{trace.before=sql->{};trace.beforeCommit=()->{};}assertTrue(hit.get(),prefix);assertEquals(baseline,state(),prefix);stages.add(prefix);}
  super.afterCandidate(candidate,facts);String body=j.queryForObject("SELECT minutes_revision_id FROM meeting WHERE id=?",String.class,meeting);var reviews=new JdbcMinutesReviews(authority,this::snapshot,pin,limits());for(String prefix:List.of("INSERT INTO result_review(","INSERT INTO result_review_evidence(","UPDATE idempotency_record SET result_id","INSERT INTO audit_event","INSERT INTO task_outbox","COMMIT")){var baseline=state();var started=new AtomicBoolean();var hit=new AtomicBoolean();trace.events.clear();trace.before=sql->{if(sql.startsWith("INSERT INTO result_review("))started.set(true);if(started.get()&&sql.startsWith(prefix)&&hit.compareAndSet(false,true))throw new IllegalStateException("TASK10_REVIEW_ROLLBACK_PROBE");};trace.beforeCommit=()->{if(prefix.equals("COMMIT")&&started.get()&&hit.compareAndSet(false,true))throw new IllegalStateException("TASK10_REVIEW_PRECOMMIT");};try{assertThrows(RuntimeException.class,()->reviews.review(actor(),meeting,"rollback-review",5,"BODY",body,"SOURCE_SUPPORT","WHOLE","SUPPORTED",null,null,UUID.randomUUID().toString()),prefix);}finally{trace.before=sql->{};trace.beforeCommit=()->{};}assertTrue(hit.get(),prefix);assertEquals(baseline,state(),prefix);stages.add("review:"+prefix);}
  // Actual low transfer budget rejects before a content-bearing SQL statement.
  trace.events.clear();var tiny=new JdbcMinutesFactsReader(authority,this::snapshot,pin,new TranscriptAcquisitionBudget(1,16777216,16777216,268435456,134217728,8388608,128,256,256));assertThrows(ama.contract.MinutesContracts.Failure.class,()->tiny.readOwner(actor(),meeting,"OWNER_REVISION",body));assertTrue(trace.events.stream().map(e->e.get("sql")).filter(Objects::nonNull).map(Object::toString).noneMatch(sql->sql.matches("(?s).*(?:SELECT |,)body(?:,| FROM ).*")));stages.add("actual-metadata-budget-before-body-transfer");
  var anchors=j.queryForList("SELECT id FROM evidence_link WHERE minutes_revision_id=? ORDER BY id",String.class,body).stream().map(e->new JdbcMinutesSavedCommands.Reanchor(e,0,5)).toList();var barrier=new CyclicBarrier(2);var racing=new JdbcMinutesSavedCommands(authority,()->{var snapshot=snapshot();try{barrier.await(15,TimeUnit.SECONDS);}catch(Exception e){throw new IllegalStateException(e);}return snapshot;},pin,limits());var executor=Executors.newFixedThreadPool(2);var answers=new ArrayList<Object>();try{var futures=new ArrayList<Future<Object>>();for(int n=0;n<2;n++){int number=n;futures.add(executor.submit(()->{try{return racing.saveBody(actor(),meeting,"race-"+number,5,body,"Race "+number,"Racing edited body",anchors,UUID.randomUUID().toString());}catch(RuntimeException e){return e;}}));}for(var f:futures)answers.add(f.get(30,TimeUnit.SECONDS));}finally{executor.shutdownNow();assertTrue(executor.awaitTermination(5,TimeUnit.SECONDS));}assertEquals(1,answers.stream().filter(Map.class::isInstance).count());var error=(RuntimeException)answers.stream().filter(RuntimeException.class::isInstance).findFirst().orElseThrow();assertTrue(error instanceof ama.contract.TranscriptContracts.Failure,"Expected authorized CAS conflict, actual "+error.getClass()+" "+error.getMessage());assertEquals(409,((ama.contract.TranscriptContracts.Failure)error).status());assertEquals(6L,j.queryForObject("SELECT revision FROM meeting WHERE id=?",Long.class,meeting));java.nio.file.Files.writeString(receipt.resolve("actual-rollback-budget-cas.json"),json.writeValueAsString(Map.of("rollbackStages",stages,"sameRevisionEditors",2,"committed",1,"loserStatus",409)));
 }
 Map<String,Object> state(){var result=new TreeMap<String,Object>();result.put("graph",completeGraph());result.put("root",j.queryForMap("SELECT * FROM meeting WHERE id=?",meeting));result.put("subject",j.queryForList("SELECT * FROM task_subject WHERE subject_id=?",meeting));result.put("projection",j.queryForList("SELECT * FROM meeting_search_projection WHERE meeting_id=?",meeting));result.put("receipts",j.queryForList("SELECT * FROM idempotency_record WHERE resource_id=? ORDER BY scope_hash",meeting));result.put("audit",j.queryForList("SELECT * FROM audit_event WHERE resource_id=? ORDER BY id",meeting));result.put("outbox",j.queryForList("SELECT * FROM task_outbox WHERE subject_id=? ORDER BY sequence_id",meeting));return result;}
 private Map<String,List<Map<String,Object>>> completeGraph(){var result=new TreeMap<String,List<Map<String,Object>>>();for(String table:List.of("minutes_revision","element_set","generation_candidate","result_review","source_locator"))result.put(table,j.queryForList("SELECT * FROM "+table+" WHERE meeting_id=? ORDER BY id",meeting));for(String table:List.of("minutes_element","sensitive_detection","background_note"))result.put(table,j.queryForList("SELECT * FROM "+table+" WHERE set_id IN(SELECT id FROM element_set WHERE meeting_id=?) ORDER BY id",meeting));for(String table:List.of("action_item","action_suggestion"))result.put(table,j.queryForList("SELECT * FROM "+table+" WHERE element_id IN(SELECT e.id FROM minutes_element e JOIN element_set s ON s.id=e.set_id WHERE s.meeting_id=?) ORDER BY element_id",meeting));result.put("evidence_link",j.queryForList("SELECT * FROM evidence_link WHERE locator_id IN(SELECT id FROM source_locator WHERE meeting_id=?) ORDER BY id",meeting));result.put("sensitive_detection_source",j.queryForList("SELECT x.* FROM sensitive_detection_source x JOIN sensitive_detection d ON d.id=x.detection_id JOIN element_set s ON s.id=d.set_id WHERE s.meeting_id=? ORDER BY x.detection_id,x.locator_id",meeting));result.put("background_note_source",j.queryForList("SELECT x.* FROM background_note_source x JOIN background_note d ON d.id=x.note_id JOIN element_set s ON s.id=d.set_id WHERE s.meeting_id=? ORDER BY x.note_id,x.locator_id",meeting));result.put("result_review_evidence",j.queryForList("SELECT x.* FROM result_review_evidence x JOIN result_review r ON r.id=x.review_id WHERE r.meeting_id=? ORDER BY x.review_id,x.evidence_id",meeting));return result;}
}
